# FILE: Chart.yaml
apiVersion: v2
name: generic-worker
description: A Helm chart for deploying a generic worker service consuming messages from a Redis queue
type: application
version: 0.1.0
appVersion: "1.0.0"
kubeVersion: ">=1.23.0-0"

---
# FILE: values.yaml
replicaCount: 2

image:
  repository: ghcr.io/example/worker
  tag: "1.0.0"
  pullPolicy: IfNotPresent

imagePullSecrets: []
nameOverride: ""
fullnameOverride: ""

serviceAccount:
  create: true
  name: ""
  annotations: {}

podAnnotations: {}
podLabels: {}

service:
  enabled: true
  type: ClusterIP
  port: 8080
  annotations: {}

resources:
  limits:
    cpu: 500m
    memory: 512Mi
  requests:
    cpu: 100m
    memory: 128Mi

podSecurityContext:
  runAsNonRoot: true
  runAsUser: 10001
  runAsGroup: 10001
  fsGroup: 2000
  fsGroupChangePolicy: "OnRootMismatch"
  seccompProfile:
    type: RuntimeDefault

securityContext:
  allowPrivilegeEscalation: false
  readOnlyRootFilesystem: true
  capabilities:
    drop:
      - ALL

env:
  WORKER_CONCURRENCY: "10"
  QUEUE_NAME: "jobs"
  LOG_LEVEL: "info"
  HTTP_METRICS: "true"
  HTTP_PORT: "8080"

redis:
  host: "redis-master"
  port: 6379
  db: 0
  useTLS: false
  username: ""
  password: ""           # If empty and existingSecret is not set, a strong password will be generated and persisted.
  existingSecret: ""     # Use an existing secret name instead of creating one
  passwordKey: "redis-password"
  secretAnnotations: {}

readinessProbe:
  enabled: true
  httpGet:
    path: /healthz
  initialDelaySeconds: 10
  periodSeconds: 10
  timeoutSeconds: 2
  failureThreshold: 6

livenessProbe:
  enabled: true
  httpGet:
    path: /livez
  initialDelaySeconds: 15
  periodSeconds: 20
  timeoutSeconds: 2
  failureThreshold: 6

startupProbe:
  enabled: true
  httpGet:
    path: /startup
  initialDelaySeconds: 5
  periodSeconds: 5
  timeoutSeconds: 2
  failureThreshold: 30

terminationGracePeriodSeconds: 30
priorityClassName: ""

topologySpreadConstraints:
  enabled: true
  maxSkew: 1
  topologyKey: "topology.kubernetes.io/zone"
  whenUnsatisfiable: "ScheduleAnyway"

autoscaling:
  enabled: false
  minReplicas: 2
  maxReplicas: 10
  targetCPUUtilizationPercentage: 80
  targetMemoryUtilizationPercentage:

pdb:
  enabled: true
  minAvailable: 1

serviceMonitor:
  enabled: false
  interval: 30s
  scrapeTimeout: 10s
  labels: {}
  annotations: {}
  path: /metrics

nodeSelector: {}
tolerations: []
affinity: {}

command: []
args: []
extraEnv: []  # e.g., [{ name: FOO, value: "bar" }]

---
# FILE: templates/_helpers.tpl
{{- define "generic-worker.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" -}}
{{- end -}}

{{- define "generic-worker.fullname" -}}
{{- if .Values.fullnameOverride -}}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" -}}
{{- else -}}
{{- $name := include "generic-worker.name" . -}}
{{- if contains $name .Release.Name -}}
{{- .Release.Name | trunc 63 | trimSuffix "-" -}}
{{- else -}}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" -}}
{{- end -}}
{{- end -}}
{{- end -}}

{{- define "generic-worker.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" -}}
{{- end -}}

{{- define "generic-worker.labels" -}}
helm.sh/chart: {{ include "generic-worker.chart" . }}
app.kubernetes.io/name: {{ include "generic-worker.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- end -}}

{{- define "generic-worker.selectorLabels" -}}
app.kubernetes.io/name: {{ include "generic-worker.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end -}}

{{- define "generic-worker.serviceAccountName" -}}
{{- if .Values.serviceAccount.create -}}
{{- if .Values.serviceAccount.name -}}
{{- .Values.serviceAccount.name -}}
{{- else -}}
{{- include "generic-worker.fullname" . -}}
{{- end -}}
{{- else -}}
{{- default "default" .Values.serviceAccount.name -}}
{{- end -}}
{{- end -}}

{{- define "generic-worker.configmapName" -}}
{{- printf "%s-config" (include "generic-worker.fullname" .) -}}
{{- end -}}

{{- define "generic-worker.redisSecretName" -}}
{{- if .Values.redis.existingSecret -}}
{{- .Values.redis.existingSecret -}}
{{- else -}}
{{- printf "%s-redis" (include "generic-worker.fullname" .) -}}
{{- end -}}
{{- end -}}

---
# FILE: templates/configmap.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ include "generic-worker.configmapName" . }}
  labels:
    {{- include "generic-worker.labels" . | nindent 4 }}
data:
  # Worker configuration
  {{- range $k, $v := .Values.env }}
  {{ $k }}: {{ $v | toString | quote }}
  {{- end }}
  # Redis connection (non-secret)
  REDIS_HOST: {{ .Values.redis.host | toString | quote }}
  REDIS_PORT: {{ .Values.redis.port | toString | quote }}
  REDIS_DB: {{ .Values.redis.db | toString | quote }}
  REDIS_USERNAME: {{ .Values.redis.username | toString | quote }}
  REDIS_USE_TLS: {{ .Values.redis.useTLS | toString | quote }}

---
# FILE: templates/secret-redis.yaml
{{- if not .Values.redis.existingSecret }}
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "generic-worker.redisSecretName" . }}
  labels:
    {{- include "generic-worker.labels" . | nindent 4 }}
  {{- with .Values.redis.secretAnnotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
type: Opaque
data:
  {{- $key := default "redis-password" .Values.redis.passwordKey -}}
  {{- printf "%s: " $key | nindent 2 -}}{{- /* key followed by value */ -}}
  {{- if .Values.redis.password -}}
  {{ .Values.redis.password | toString | b64enc }}
  {{- else -}}
  {{- $secretName := include "generic-worker.redisSecretName" . -}}
  {{- $existing := (lookup "v1" "Secret" .Release.Namespace $secretName) -}}
  {{- if and $existing (hasKey $existing.data $key) -}}
  {{ index $existing.data $key }}
  {{- else -}}
  {{ randAlphaNum 32 | b64enc }}
  {{- end -}}
  {{- end -}}
{{- end }}

---
